//! Baseline acceptor: Endpoint A (LAN gateway role).
//!
//! Binds an iroh endpoint with the default relay configuration, prints its
//! EndpointId + addresses, accepts one baseline echo connection, echoes all
//! bytes back, and records path telemetry (plan E0 / PR 1).
//!
//! The first bytes of the stream are a run-id header generated by the
//! dialer; the acceptor records that id so the two result rows of one
//! physical run can be paired.

use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use anyhow::{Context, Result};
use clap::Parser;
use common::{ExperimentResult, SelectedPath, TEST_PAYLOAD_BYTES};
use iroh::endpoint::PathEvent;
use tokio_stream::StreamExt;

/// Experiment-wide upper bound for waiting on a relay -> direct migration
/// after the payload transfer completes.
const DIRECT_MIGRATION_TIMEOUT: Duration = Duration::from_secs(30);

/// Upper bound on the run-id header length; anything larger is a corrupt or
/// foreign stream, not a runaway allocation.
const RUN_ID_MAX_BYTES: usize = 1024;

/// Upper bound for waiting on the dialer to close its side of the connection
/// before this endpoint closes.
const PEER_CLOSE_TIMEOUT: Duration = Duration::from_secs(30);

/// Shared telemetry snapshot written by the path-event watcher task.
struct PathTelemetry {
    first_direct: Option<Duration>,
    /// Whether the most recent `Selected` event chose a relay path.
    last_selected_is_relay: bool,
    /// Whether a direct path was observed at any point, including one
    /// seeded from the live snapshot before the event subscription. A later
    /// relay fallback overwrites `last_selected_is_relay` but must not erase
    /// this.
    direct_ever: bool,
}

#[derive(Parser)]
struct Args {
    /// File to append a JSON result line to (JSONL).
    #[arg(long)]
    results: String,
    /// Network profile label recorded in the result.
    #[arg(long, default_value = "unspecified")]
    network_profile: String,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
        )
        .init();
    let args = Args::parse();

    let runtime = tokio::runtime::Runtime::new()?;
    let outcome = runtime.block_on(run(&args.network_profile));

    // Persist a result line even on failure (with failure_reason set).
    let result = match outcome {
        Ok(r) => r,
        Err(e) => {
            let mut r = common::new_result(
                format!("baseline-accept-{}", run_suffix()),
                "baseline",
                "acceptor",
                &args.network_profile,
            );
            r.failure_reason = Some(format!("{e:#}"));
            r
        }
    };
    common::append_result_line(&args.results, &result)?;

    if let Some(reason) = result.failure_reason.clone() {
        anyhow::bail!("run failed: {reason}");
    }
    Ok(())
}

async fn run(network_profile: &str) -> Result<ExperimentResult> {
    let endpoint = iroh::Endpoint::builder(iroh::endpoint::presets::N0)
        .bind()
        .await
        .context("failed to bind iroh endpoint")?;

    endpoint.set_alpns(vec![common::BASELINE_ALPN.to_vec()]);
    println!("ENDPOINT_ID={}", endpoint.id());
    for addr in endpoint.addr().addrs {
        println!("ADDR={addr}");
    }

    // Accept exactly one connection for the baseline run. The acceptor cannot
    // know the peer's dial-start instant, and timing from its own startup
    // would include the arbitrary delay until the dialer is launched, so
    // time_to_direct_ms here is measured from accept completion; a direct
    // path already selected by then stays null (the paired dialer row, same
    // run_id, carries that transition).
    let t_conn = Instant::now();
    let conn = endpoint
        .accept()
        .await
        .context("endpoint closed before incoming connection")?
        .accept()?
        .await
        .context("accept failed")?;

    println!("CONNECTED_AT_MS={}", t_conn.elapsed().as_millis());
    let t_start = Instant::now();

    // Watch path events from before the echo transfer starts, so a
    // relay -> direct migration during the transfer is observed.
    // PathEventStream is 'static; the snapshot mutex keeps observed values
    // even though the stream stays pending on a live connection.
    let mut events = conn.path_events();
    let telemetry = Arc::new(Mutex::new(PathTelemetry {
        first_direct: None,
        last_selected_is_relay: true,
        direct_ever: false,
    }));
    let watcher = tokio::spawn({
        let telemetry = Arc::clone(&telemetry);
        async move {
            while let Some(event) = events.next().await {
                match event {
                    PathEvent::Selected { remote_addr, .. } => {
                        let mut t = telemetry.lock().unwrap();
                        t.last_selected_is_relay = remote_addr.is_relay();
                        if !remote_addr.is_relay() {
                            t.direct_ever = true;
                            if t.first_direct.is_none() {
                                t.first_direct = Some(t_start.elapsed());
                            }
                        }
                        tracing::info!(addr = %remote_addr, "path selected");
                    }
                    PathEvent::Opened { remote_addr, .. } => {
                        tracing::info!(addr = %remote_addr, "path opened");
                    }
                    _ => {}
                }
            }
        }
    });

    // The direct path can already be selected when accept completes, before
    // the event stream is subscribed. Seed the last-selected kind and the
    // ever-observed bit from the live snapshot, but not first_direct: a
    // selection before accept completed has no measurable origin on this
    // side. Keeping direct_ever separate preserves the success when a later
    // relay event overwrites last_selected_is_relay.
    {
        let paths = conn.paths();
        if let Some(p) = paths.iter().find(|p| p.is_selected()) {
            let mut t = telemetry.lock().unwrap();
            t.last_selected_is_relay = p.is_relay();
            t.direct_ever |= !p.is_relay();
        }
    }

    // From here on, failures happen after the connection exists, so the
    // accumulated path telemetry must survive into the result row; a failed
    // transfer is not a direct-connection failure.
    let mut failure: Option<String> = None;
    let mut echoed: u64 = 0;
    // Run id sent by the dialer; None only when the stream failed before the
    // header arrived, in which case the failure row cannot be paired anyway.
    let mut run_id: Option<String> = None;

    match conn.accept_bi().await {
        Err(e) => failure = Some(format!("accept_bi failed: {e:#}")),
        Ok((mut send, mut recv)) => {
            // Read [u32 LE length][run id], record it, echo it back so the
            // dialer's verification covers the header as well.
            let mut len_buf = [0u8; 4];
            let id = async {
                recv.read_exact(&mut len_buf).await?;
                let len = u32::from_le_bytes(len_buf) as usize;
                if len > RUN_ID_MAX_BYTES {
                    anyhow::bail!("run id length {len} exceeds {RUN_ID_MAX_BYTES}");
                }
                let mut id_buf = vec![0u8; len];
                recv.read_exact(&mut id_buf).await?;
                Ok::<_, anyhow::Error>(id_buf)
            }
            .await;
            match id {
                Err(e) => failure = Some(format!("run id header read failed: {e:#}")),
                Ok(id_buf) => {
                    // Keep the parsed id even if echoing it fails: the two
                    // failure rows can still be paired, since the id was
                    // successfully received.
                    run_id = Some(String::from_utf8_lossy(&id_buf).into_owned());
                    let echo_err = send.write_all(&len_buf).await.err();
                    let echo_err = match echo_err {
                        None => send.write_all(&id_buf).await.err(),
                        some => some,
                    };
                    if let Some(e) = echo_err {
                        failure = Some(format!("run id echo failed: {e:#}"));
                    }
                }
            }

            if failure.is_none() {
                // Echo loop: read everything the dialer sends, write it back.
                let mut buf = vec![0u8; 64 * 1024];
                while echoed < TEST_PAYLOAD_BYTES as u64 {
                    match recv.read(&mut buf).await {
                        Err(e) => {
                            failure = Some(format!("read failed: {e:#}"));
                            break;
                        }
                        Ok(None) => {
                            failure = Some("stream ended early".into());
                            break;
                        }
                        Ok(Some(n)) => {
                            if let Err(e) = send.write_all(&buf[..n]).await {
                                failure = Some(format!("echo write failed: {e:#}"));
                                break;
                            }
                            echoed += n as u64;
                        }
                    }
                }
                if failure.is_none() {
                    // A failed finish is a transfer failure, not a reason to
                    // discard the accumulated telemetry (the run id, echoed
                    // byte count, and path state stay in the result row).
                    if let Err(e) = send.finish() {
                        failure = Some(format!("send finish failed: {e:#}"));
                    }
                }
            }
        }
    }
    println!("ECHOED_BYTES={echoed}");
    let elapsed = t_start.elapsed();

    // Wait for the direct migration instead of a fixed sleep: a fixed window
    // would truncate observation on high-latency / lossy profiles and bias
    // direct-success rates. Stop as soon as a direct path was observed, the
    // connection closed, or the experiment-wide timeout expired.
    let (first_direct, last_selected_is_relay, direct_ever) = loop {
        {
            let t = telemetry.lock().unwrap();
            if t.direct_ever
                || first_direct_ready(&t)
                || conn.close_reason().is_some()
                || t_start.elapsed() > DIRECT_MIGRATION_TIMEOUT
            {
                break (t.first_direct, t.last_selected_is_relay, t.direct_ever);
            }
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    };
    watcher.abort();

    let stats = conn.stats();
    // Final state comes from the live path snapshot; the event snapshot is
    // only used for transition timing. If the direct path was selected before
    // the watcher subscribed, or its event is still pending, the live snapshot
    // still reports it correctly.
    let (selected_rtt, selected_is_relay) = {
        let paths = conn.paths();
        match paths.iter().find(|p| p.is_selected()) {
            Some(p) => (Some(p.rtt()), p.is_relay()),
            None => (None, last_selected_is_relay),
        }
    };
    if let Some(ms) = first_direct {
        println!("TIME_TO_DIRECT_MS={}", ms.as_millis());
    }

    let mut result = common::new_result(
        run_id.unwrap_or_else(|| format!("baseline-accept-{}", run_suffix())),
        "baseline",
        "acceptor",
        network_profile,
    );
    result.direct_connection_success = direct_ever || first_direct.is_some() || !selected_is_relay;
    result.time_to_direct_ms = first_direct.map(|d| d.as_millis() as u64);
    result.selected_path = Some(if selected_is_relay {
        SelectedPath::Relay
    } else {
        SelectedPath::DirectIp
    });
    // The plan's direct_path_rtt_ms is the RTT of an observed direct path;
    // a relay path's RTT must not be recorded under it.
    result.direct_path_rtt_ms = if !selected_is_relay {
        selected_rtt.map(|d| d.as_millis() as u64)
    } else {
        None
    };
    result.payload_bytes = echoed;
    // A failed transfer reports partial payload_bytes (how far it got) but no
    // throughput: the elapsed time of an aborted run does not measure the
    // path.
    if failure.is_none() {
        let secs = elapsed.as_secs_f64().max(0.001);
        result.media_throughput_mbps = Some(echoed as f64 * 8.0 / secs / 1_000_000.0);
    }
    result.failure_reason = failure;

    println!(
        "RTT_MS={}",
        selected_rtt.map(|d| d.as_millis()).unwrap_or(0)
    );
    println!("ELAPSED_SECS={:.3}", elapsed.as_secs_f64());
    println!(
        "UDP_TX_DATAGRAMS={} UDP_RX_DATAGRAMS={}",
        stats.udp_tx.datagrams, stats.udp_rx.datagrams
    );

    // Close this endpoint only after the dialer closed its side: a QUIC
    // close is abrupt and discards echo bytes still in flight, which would
    // turn a successful transfer into a dialer-side "connection lost"
    // failure. The dialer closes after reading the full echo, so its close
    // implies delivery.
    let t_close_wait = Instant::now();
    while conn.close_reason().is_none() && t_close_wait.elapsed() < PEER_CLOSE_TIMEOUT {
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    endpoint.close().await;
    Ok(result)
}

/// True once a direct transition was ever observed.
fn first_direct_ready(t: &PathTelemetry) -> bool {
    t.first_direct.is_some()
}

fn run_suffix() -> String {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0)
        .to_string()
}
